import { WeatherFileSchema } from '@jaga-daerah/contracts';

import weatherJson from '@/data/weather.json';

// Generated by `uv run python -m jaga_etl.weather --snapshot data/raw/bmkg-weather/<id> --output
// ../../apps/web/src/data/weather.json` from BMKG's normal rainfall for 1981-2010; parsed at build
// time so a malformed file fails the build.
export const WEATHER = WeatherFileSchema.parse(weatherJson);
